/**
 * WordPress dependencies.
 */
import { Notice } from "@wordpress/components";

/**
 * Internal dependencies.
 */

import { useNotice } from "../../context/hooks";

import Home from "./tabs/home";
import Extensions from "./tabs/extensions";
import Blocks from "./tabs/blocks";
import Preferences from "./tabs/preferences";

const Main = ({ activeTab }) => {
	const { notice, hasNotice, clearNotice } = useNotice();

	const renderTabContent = () => {
		switch (activeTab) {
			case "blocks":
				return <Blocks />;
			case "extensions":
				return <Extensions />;
			case "preferences":
				return <Preferences />;
			default:
				return <Home />;
		}
	};

	return (
		<main className="blocklayouts-dashboard__main">
			{hasNotice && (
				<Notice
					status={notice.type}
					isDismissible
					className="blocklayouts-dashboard__notice"
					onDismiss={clearNotice}
				>
					{notice.message}
				</Notice>
			)}
			{renderTabContent()}
		</main>
	);
};

export default Main;
